/** Complemento para incorporar la información en el caso de Exportación de Mercancías en definitiva.**/
export interface ComercioExterior extends XastElement {
	type: 'element';
	name: 'ComercioExterior';
	attributes: {
		/** Atributo derivado de la excepción de certificados de Origen de los Tratados de Libre Comercio que ha celebrado México con diversos países. 0 = No Funge como certificado de origen 1 = Funge como certificado de origen.	**/
		CertificadoOrigen?: ComercioExteriorCertificadoOrigen;
		/** Atributo que indica la clave de pedimento que se haya declarado conforme al apéndice 2 del anexo 22 de las reglas generales de comercio exterior.	**/
		ClaveDePedimento?: CClavePedimento;
		/** Atributo que indica la clave del INCOTERM aplicable a la factura.	**/
		Incoterm?: CINCOTERM;
		/** Atributo opcional para expresar el folio del certificado de origen o el folio fiscal del CFDI con el que se pagó la expedición del certificado de origen.	**/
		NumCertificadoOrigen?: string;
		/** Atributo opcional que indica el número de exportador confiable, conforme al artículo 22 del Anexo 1 del Tratado de Libre Comercio con la Asociación Europea y a la Decisión de la Comunidad Europea.	**/
		NumeroExportadorConfiable?: string;
		/** Atributo opcional en caso de ingresar alguna información adicional, como alguna leyenda que debe incluir el CFDI.	**/
		Observaciones?: string;
		/** Atributo que indica si la factura tiene o no subdivisión. Valores posibles:0 - no tiene subdivisión,1 - si tiene subdivisión.	**/
		Subdivision?: ComercioExteriorSubdivision;
		/** Atributo que indica el número de pesos mexicanos que equivalen a un dólar de Estados Unidos, de acuerdo al artículo 20 del Código Fiscal de la Federación.	**/
		TipoCambioUSD?: string;
		/** Atributo requerido que indica el tipo de operación de comercio exterior que se realiza, puede ser importación o exportación, A = exportación de servicios. 2 = exportación.	**/
		TipoOperacion: CTipoOperacion;
		/** Atributo que indica el importe total del comprobante en dólares de Estados Unidos.	**/
		TotalUSD?: string;
		/** Atributo requerido que indica la versión del complemento.	**/
		Version: string;
	};
	children: (ComercioExteriorDestinatario | ComercioExteriorEmisor | ComercioExteriorMercancias | ComercioExteriorReceptor)[];
}

